// Prepare the generated 2x2 floating-pose source as four 64x80 directional frames.
// Art is generated by imagegen; this step only keys, slices and resamples the atlas.
const sharp=require(process.cwd()+'/node_modules/sharp');
(async()=>{
 const input='public/assets/gift-shade-float-v2-source.png';
 const {data,info}=await sharp(input).ensureAlpha().raw().toBuffer({resolveWithObject:true});
 // The generator returned opaque pixels, so the final source uses a flat magenta key.
 // Its grey/ivory/charcoal subject contains no magenta; remove key spill at the edge too.
 for(let i=0;i<data.length;i+=4){
  const spill=Math.min(data[i],data[i+2])-data[i+1];
  if(spill>40){data[i]=data[i+1]=data[i+2]=data[i+3]=0;}
  else if(spill>8){data[i]-=spill;data[i+2]-=spill;}
 }
 const source=await sharp(data,{raw:info}).png().toBuffer(),layers=[];
 for(let frame=0;frame<4;frame++){
  const col=frame%2,row=Math.floor(frame/2);
  const left=Math.floor(col*info.width/2),top=Math.floor(row*info.height/2);
  const quadrant=await sharp(source).extract({left,top,width:Math.floor((col+1)*info.width/2)-left,height:Math.floor((row+1)*info.height/2)-top}).png().toBuffer();
  const crop=await sharp(quadrant).trim().png().toBuffer();
  const meta=await sharp(crop).metadata(),width=Math.round(meta.width/meta.height*62);
  if(width>60)throw Error('Unexpected floating pose width: '+width);
  layers.push({input:await sharp(crop).resize(width,62,{kernel:'nearest'}).png().toBuffer(),left:frame*64+Math.floor((64-width)/2),top:14});
 }
 await sharp({create:{width:256,height:80,channels:4,background:'#00000000'}}).composite(layers).png().toFile('public/assets/gift-shade-float-v2.png');
 console.log('Packed four floating directions: down, left, right, up (64x80, alpha).');
})().catch(error=>{console.error(error);process.exitCode=1;});
